effect.shader:

// --- NOISE FUNCTIONS ---
float hash(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

// Value Noise with Smoothstep
float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * f * (f * (f * 6.0 - 15.0) + 10.0); // Quintic

    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));

    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Fractal Brownian Motion
float fbm(vec2 p) {
    float f = 0.0;
    float amp = 0.5;
    for(int i = 0; i < 4; i++) {
        f += amp * noise(p);
        p *= 2.0;
        amp *= 0.5;
    }
    return f;
}

void main() {
    vec2 uv = acScreenNorm;

    // 1. Setup Coordinates
    vec2 noise_uv = uv;
    noise_uv.x *= acScreenSize.x / acScreenSize.y; 

    // 2. Generate Turbulence
    float t = acTime * fireSpeed;
    vec2 flow = vec2(fbm(noise_uv * flameDetail + vec2(0.0, t)), 
                     fbm(noise_uv * flameDetail + vec2(t * 1.3, 0.0)));

    // 3. Calculate Distance to Edge
    float dist_x = min(uv.x, 1.0 - uv.x);
    float dist_y = min(uv.y, 1.0 - uv.y);
    float dist_to_edge = min(dist_x, dist_y);

    // 4. Distort the Edge (Applied Settings Here)
    // We use distortionScale for the noise frequency
    float wave = fbm(noise_uv * distortionScale - t * 2.0 + flow);

    // We use distortionStrength to determine how much it affects the border
    float border_shape = dist_to_edge + (wave * distortionStrength); 

    // 5. Create the Fire Mask
    float heat = 1.0 - smoothstep(0.0, borderSize, border_shape);

    // 6. Color Mapping
    vec3 col = vec3(0.0);
    if(heat > 0.0) {
        // Core 
        col += vec3(1.0, 1.0, 0.8) * pow(heat, 6.0);
        // Middle 
        col += vec3(1.0, 0.5, 0.0) * pow(heat, 3.0) * 1.5;
        // Tips 
        col += vec3(0.5, 0.0, 0.0) * heat;
    }

    col *= fireIntensity;
    col *= step(0.0, heat); 

    // Apply manual tint override (optional, but requested implicitly)
    // The original had a constant FIRE_TINT vec3(1.0, 0.5, 0.2)
    // We mix towards it or multiply? Let's Multiplying it allows tinting.
    // But since default colors are reddish/orange, multiplying by orange makes it very deep orange.
    // Let's assume the user wants to filter the result.
    // Note: The original code defined FIRE_TINT but didn't use it in the mainImage provided.
    // We will leave it as an option.
    // To make it neutral by default, we can't easily. 
    // We'll just provide the uniform. If the user wants to use it, they can.

    // Simple transparency based on heat
    float alpha = smoothstep(0.0, 0.1, heat);

    gl_FragColor = vec4(col, alpha);
}
